LAYER = v2225.SerializedAbilitiesData.SerializedLayer
LAYER_KIND = v2225.SerializedAbilitiesData.SerializedAbilitiesLayer

GOLDENS = [
    pytest.param(
        v2225.UpdateAbilitiesPacket(
            data=v2225.SerializedAbilitiesData(
                target_player=7,
                player_permissions=v2225.PlayerPermissionLevel.OPERATOR,
                command_permissions=v2225.CommandPermissionLevel.OWNER,
                layers=[
                    LAYER(
                        serialized_layer=LAYER_KIND.BASE,
                        abilities_set=0x600,
                        ability_values=0x200,
                        fly_speed=0.05,
                        vertical_fly_speed=1.0,
                        walk_speed=0.1,
                    ),
                    LAYER(
                        serialized_layer=LAYER_KIND.COMMANDS,
                        abilities_set=0x40,
                        ability_values=0x40,
                        fly_speed=0.0,
                        vertical_fly_speed=0.0,
                        walk_speed=0.0,
                    ),
                ],
            )
        ),
        TWO_LAYERS,
        id="two-layers",
    ),
    pytest.param(
        v2225.UpdateAbilitiesPacket(
            data=v2225.SerializedAbilitiesData(
                target_player=-1,
                player_permissions=v2225.PlayerPermissionLevel.VISITOR,
                command_permissions=v2225.CommandPermissionLevel.ANY,
                layers=[],
            )
        ),
        NO_LAYERS,
        id="no-layers-as-a-lone-zero-count",
    ),
    pytest.param(
        v2225.UpdateAbilitiesPacket(
            data=v2225.SerializedAbilitiesData(
                target_player=0,
                player_permissions=v2225.PlayerPermissionLevel.VISITOR,
                command_permissions=v2225.CommandPermissionLevel.ANY,
                layers=[
                    LAYER(
                        serialized_layer=LAYER_KIND.BASE,
                        abilities_set=0,
                        ability_values=0,
                        fly_speed=0.0,
                        vertical_fly_speed=0.0,
                        walk_speed=0.0,
                    )
                ]
                * 128,
            )
        ),
        LAYERS_128,
        id="128-layers-with-a-two-byte-count",
    ),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_abilities_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_abilities_decodes_from_its_golden(packet, golden):
    assert v2225.UpdateAbilitiesPacket.from_bytes(golden) == packet
